  Object.assign(this,{getWorld,onClose,getLedgerData,onMarketCommodity,onMarketRange});this.view=LEDGER_TABS[0].id;this.portId=null;this.data=createDemoLedgerData();this.scrollPositions=new Map();this.renderKey='';this.nextRefreshAt=0;this.refreshIntervalMs=2000;
