  const close=node('button','Close','port-close');close.setAttribute('aria-label','Close port ledger');close.title='Close ledger';close.onclick=()=>this.dialog.close();top.append(identity);this.closeButton=close;
  const bar=node('div',undefined,'port-dashboard-bar'),leftTabs=node('div',undefined,'port-tab-side port-tab-side-left'),rightTabs=node('div',undefined,'port-tab-side port-tab-side-right');this.leftTabs=leftTabs;this.rightTabs=rightTabs;this.tabs=new Map();for(const definition of LEDGER_TABS){const tab=node('button');tab.type='button';tab.title=definition.title;tab.setAttribute('aria-label',definition.title);tab.setAttribute('aria-controls','port-ledger-content');const label=node('span',definition.title,'port-tab-title');label.setAttribute('aria-hidden','true');tab.append(tabIcon(definition),label);tab.onclick=()=>this.changeView(definition.id);this.tabs.set(definition.id,tab);}bar.append(leftTabs,rightTabs);this.bar=bar;
