 open(port,{data=null}={}){this.portId=port?.id??null;this.port=port;this.data=data??this.getLedgerData?.(port)??createDemoLedgerData(port);this.view=LEDGER_TABS[0].id;this.scrollPositions.clear();this.renderKey='';this.syncIdentity();this.renderPage();this.renderKey=this.snapshotKey(port,this.data);this.nextRefreshAt=Date.now()+this.refreshIntervalMs;if(!this.dialog.open)this.dialog.showModal();}
