 renderBlocks(blocks,source){return (blocks??[]).map(block=>this.renderBlock(block,source)).filter(Boolean);}
 renderBlock(block,source){const value=resolveLedgerPath(source,block.path);switch(block.type){case'eyebrow':return node('span',formatLedgerValue(value),'port-kicker');case'heading':return node('h3',formatLedgerValue(value));case'sectionHeader':{const header=node('div',undefined,'ledger-section-header');if(block.icon)header.append(inlineIcon(block.icon,`${formatLedgerValue(value)} icon`));header.append(node('h3',formatLedgerValue(value)));return header;}case'paragraph':return node('p',formatLedgerValue(value),'port-context');case'note':return node('p',formatLedgerValue(value),'port-footnote');case'callout':return node('aside',formatLedgerValue(value),'ledger-callout');case'divider':return node('hr',undefined,'ledger-divider');case'list':{const list=node('ul',undefined,'ledger-list');for(const entry of Array.isArray(value)?value:[])list.append(node('li',formatLedgerValue(entry)));return list;}case'metrics':{const grid=node('div',undefined,'port-metrics');for(const metric of Array.isArray(value)?value:[])grid.append(this.renderMetric(metric));return grid;}case'metric':return this.renderMetric(value);case'keyValues':return this.renderKeyValues(Array.isArray(value)?value:[]);case'resource':return this.renderResources(Array.isArray(value)?value:[value]);case'timeline':return this.renderTimeline(Array.isArray(value)?value:[]);case'chart':return this.renderChartWithControls(value);case'marketKnowledge':return this.renderMarketKnowledge(Array.isArray(value)?value:[]);case'source':return this.renderSource(value);case'status':return node('span',formatLedgerValue(value?.label??value),'ledger-status '+(value?.tone??''));case'table':return block.interactive==='marketCommodity'?this.renderMarketTable(block,Array.isArray(value)?value:[]):this.renderTable(block,Array.isArray(value)?value:[]);default:return null;}}
