 renderSource(source={}){return node('p',`Observed ${source.observedAt??'unknown'} · ${formatLedgerValue(source.confidence,'percent')} confidence`,'ledger-source-stamp');}
 renderChart(chart={}){const figure=node('figure',undefined,'ledger-chart'),caption=node('figcaption',chart.title??'Chart'),canvas=node('canvas');canvas.width=480;canvas.height=180;canvas.setAttribute?.('role','img');canvas.setAttribute?.('aria-label',`${chart.title??'Chart'}: ${(chart.points??[]).map(point=>`${point.label} ${point.value}`).join(', ')}`);figure.append(caption,canvas);const context=canvas.getContext?.('2d');if(!context)return figure;const points=(Array.isArray(chart.points)?chart.points:[]).filter(point=>Number.isFinite(Number(point.value)));if(!points.length)return figure;const width=canvas.width,height=canvas.height,pad={left:48,right:12,top:18,bottom:28},values=points.map(point=>Number(point.value)),min=Math.min(...values),max=Math.max(...values),spread=max-min,axisPad=spread>0?Math.max(.1,spread*.12):Math.max(.1,Math.abs(max)*.1),low=Math.max(0,min-axisPad),high=Math.max(low+1e-6,max+axisPad),range=high-low;context.clearRect(0,0,width,height);context.strokeStyle='#8c6d47';context.lineWidth=1;context.beginPath();context.moveTo(pad.left,pad.top);context.lineTo(pad.left,height-pad.bottom);context.lineTo(width-pad.right,height-pad.bottom);context.stroke();context.font='11px Georgia';for(let index=0;index<=4;index++){const value=low+range*index/4,y=height-pad.bottom-(value-low)/range*(height-pad.top-pad.bottom);context.strokeStyle='#8c6d4738';context.beginPath();context.moveTo(pad.left,y);context.lineTo(width-pad.right,y);context.stroke();context.fillStyle='#5a3a22';context.textAlign='right';context.fillText(formatLedgerValue(value,'money'),pad.left-6,y+4);}context.strokeStyle='#8f4e3f';context.lineWidth=2;context.beginPath();points.forEach((point,index)=>{const x=pad.left+(width-pad.left-pad.right)*(index/Math.max(1,points.length-1)),y=height-pad.bottom-(Number(point.value)-low)/range*(height-pad.top-pad.bottom);if(index)context.lineTo(x,y);else context.moveTo(x,y);});context.stroke();const labelCount=Math.min(6,points.length),labelIndexes=new Set(Array.from({length:labelCount},(_,index)=>Math.round(index*(points.length-1)/Math.max(1,labelCount-1))));context.fillStyle='#5a3a22';context.font='12px Georgia';context.textAlign='center';for(const index of labelIndexes){const point=points[index],x=pad.left+(width-pad.left-pad.right)*(index/Math.max(1,points.length-1));context.fillText(String(point.label),x,height-9);}return figure;}
 renderChartWithControls(chart={}){const figure=this.renderChart(chart),controls=node('div',undefined,'ledger-chart-controls');for(const range of chart.ranges??[]){const button=node('button',range.label);button.type='button';button.setAttribute('aria-pressed',String(Number(chart.selectedRange??0)===Number(range.seconds)));button.onclick=()=>this.onMarketRange?.(this.portId,Number(range.seconds));controls.append(button);}figure.append(controls);return figure;}
 renderMarketTable(block,rows){const section=node('section',undefined,'ledger-table-block'),table=node('table',undefined,'ledger-data-table'),head=node('thead'),headRow=node('tr'),body=node('tbody');for(const column of block.columns??[])headRow.append(node('th',column.label));head.append(headRow);for(const row of rows){const tr=node('tr');for(const column of block.columns??[]){const td=node('td');if(column.interactive==='marketCommodity'){const button=node('button',undefined,'ledger-market-link');button.type='button';button.setAttribute('aria-label',`Show ${row.goods??'commodity'} price history`);if(row.icon)button.append(inlineIcon(row.icon,row.goods));button.append(node('span',formatLedgerValue(row?.[column.key],column.format)));button.onclick=()=>this.onMarketCommodity?.(this.portId,row.commodityId);td.append(button);}else td.append(node('span',formatLedgerValue(row?.[column.key],column.format)));tr.append(td);}body.append(tr);}table.append(head,body);section.append(table);return section;}
 renderMarketKnowledge(rows){const section=node('section',undefined,'ledger-table-block ledger-market-knowledge'),table=node('table',undefined,'ledger-data-table'),head=node('thead'),headRow=node('tr'),body=node('tbody');for(const label of ['Port','Goods','Wanted','Offers','Age'])headRow.append(node('th',label));head.append(headRow);for(const row of rows){const tr=node('tr'),goods=node('span',undefined,'ledger-knowledge-goods');if(row.icon)goods.append(inlineIcon(row.icon,row.goods));goods.append(node('span',row.goods));for(const value of [row.port,goods,row.wanted,row.offers,row.age]){const td=node('td');if(value===goods)td.append(value);else td.append(node('span',formatLedgerValue(value)));tr.append(td);}body.append(tr);}table.append(head,body);section.append(table);return section;}
 renderTable(block,rows){const section=node('section',undefined,'ledger-table-block'),table=node('table',undefined,'ledger-data-table'),head=node('thead'),headRow=node('tr'),body=node('tbody');for(const column of block.columns??[])headRow.append(node('th',column.label));head.append(headRow);for(const row of rows){const tr=node('tr');for(const column of block.columns??[])tr.append(node('td',formatLedgerValue(row?.[column.key],column.format)));body.append(tr);}table.append(head,body);section.append(table);return section;}
 createTurnPage(direction){const source=this.content?.children?.[direction==='forward'?1:0];if(!source||typeof source.cloneNode!=='function')return null;const turn=source.cloneNode(true);turn.className=`port-page ledger-turning-page ledger-turning-page-${direction}`;turn.setAttribute?.('aria-hidden','true');turn.setAttribute?.('role','presentation');turn.removeAttribute?.('id');for(const element of turn.querySelectorAll?.('[id]')??[])element.removeAttribute('id');return turn;}
